import {useState} from 'react'
import {Button, CounterLabel, Tooltip, SelectPanel} from '@primer/react'
import type {SelectPanelItemInput as ItemInput} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {OrganizationIcon, TriangleDownIcon} from '@primer/octicons-react'
import styles from '../styles/BusinessTeamsCreateEditView.module.css'
import {useQuery, useMutation} from '@github-ui/react-query'
import {verifiedFetchJSON, verifiedFetch} from '@github-ui/verified-fetch'
import {useDebounce} from '@github-ui/use-debounce'
import type {Organization} from '../types'

export interface OrganizationSuggestions {
  organizations: Organization[]
  totalAvailableCount: number
}

export interface OrganizationSelectPanelProps {
  enterpriseSlug: string
  alreadyAssignedOrgCount: number
  initialSelectedIds: number[]
  onOrganizationsAdded: (addedOrganizations: Organization[]) => void
  enterpriseTeamsOrgAssignmentLimit: number
  teamSlug?: string
}

export function OrganizationSelectPanel({
  enterpriseSlug,
  alreadyAssignedOrgCount,
  initialSelectedIds,
  onOrganizationsAdded,
  enterpriseTeamsOrgAssignmentLimit,
  teamSlug,
}: OrganizationSelectPanelProps) {
  const [debouncedFilter, setDebouncedFilter] = useState('')
  const [isSelectPanelOpen, setSelectPanelOpen] = useState(false)

  const {
    isError: searchQueryError,
    isPending: searchQueryPending,
    data: searchResults,
  } = useQuery<OrganizationSuggestions>({
    queryKey: ['eligibleOrganizations', enterpriseSlug, debouncedFilter, initialSelectedIds, teamSlug],
    queryFn: async () => {
      if (teamSlug) {
        const response = await verifiedFetchJSON(
          `/enterprises/${enterpriseSlug}/teams/${teamSlug}/organization_suggestions?query=${encodeURIComponent(
            debouncedFilter,
          )}`,
          {
            method: 'GET',
            headers: {Accept: 'application/json'},
          },
        )

        if (response.ok) {
          return await response.json()
        } else {
          throw new Error(`${response.status} on ${response.url}`)
        }
      } else {
        // We use a post to avoid being bounded by query string limit with the org list.
        const response = await verifiedFetchJSON(`/enterprises/${enterpriseSlug}/organization_suggestions`, {
          method: 'POST',
          headers: {Accept: 'application/json'},
          body: {
            query: debouncedFilter,
            selectedOrganizationIds: initialSelectedIds,
          },
        })

        if (response.ok) {
          return await response.json()
        } else {
          throw new Error(`${response.status} on ${response.url}`)
        }
      }
    },
    enabled: isSelectPanelOpen,
  })
  const eligibleOrganizations: Organization[] = searchResults?.organizations || []

  const [addingSelectedOrganizations, setAddingSelectedOrganizations] = useState<Organization[]>([])
  const [filter, setFilter] = useState('')

  const {
    mutate: addOrganizations,
    isError: addErrorOccurred,
    error: addError,
  } = useMutation({
    mutationFn: async () => {
      const formData = new FormData()
      for (const org of addingSelectedOrganizations) {
        formData.append('organization_ids[]', org.id.toString())
      }

      const response = await verifiedFetch(`/enterprises/${enterpriseSlug}/teams/${teamSlug}/organizations`, {
        method: 'POST',
        headers: {Accept: 'application/json'},
        body: formData,
      })

      const json = await response.json()
      if (!response.ok) {
        throw new Error(json.error || `${response.status} on ${response.url}`)
      }

      return json
    },
    onSuccess: () => {
      onOrganizationsAdded(addingSelectedOrganizations)
      handleCancel()
    },
  })

  const assignmentAllowedToAddLimitReached =
    (alreadyAssignedOrgCount ?? 0) + initialSelectedIds.length + addingSelectedOrganizations.length >=
    enterpriseTeamsOrgAssignmentLimit

  eligibleOrganizations.sort((a, b) => {
    const aIsSelected = addingSelectedOrganizations.includes(a)
    const bIsSelected = addingSelectedOrganizations.includes(b)
    if (aIsSelected && !bIsSelected) return -1
    if (!aIsSelected && bIsSelected) return 1
    return 0
  })

  function handleAddOrganizations() {
    if (!teamSlug) {
      onOrganizationsAdded(addingSelectedOrganizations)
      handleCancel()
    } else {
      addOrganizations()
    }
  }

  function handleCancel() {
    setAddingSelectedOrganizations([])
    setSelectPanelOpen(false)
  }

  function handleFilterChange(newFilter: string) {
    setFilter(newFilter)
    updateDebouncedFilter(newFilter)
  }

  const updateDebouncedFilter = useDebounce((newFilter: string) => {
    setDebouncedFilter(newFilter)
  }, 300)

  const items: ItemInput[] = [
    ...eligibleOrganizations.map(org => ({
      id: org.id,
      text: org.name || org.login,
      selected: addingSelectedOrganizations.some(o => o.id === org.id),
      disabled: assignmentAllowedToAddLimitReached && !addingSelectedOrganizations.some(o => o.id === org.id),
      leadingVisual: () => (
        <GitHubAvatar square src={org.avatarUrl} alt={`Icon for the ${org.name || org.login} organization`} />
      ),
      'data-testid': `org-${org.id}`,
    })),
  ]

  return (
    <>
      {assignmentAllowedToAddLimitReached && !isSelectPanelOpen ? (
        <Tooltip
          text={
            teamSlug
              ? `Cannot add more organizations, team has reached the ${enterpriseTeamsOrgAssignmentLimit} organization limit.`
              : `You can't select more organizations — you've reached the ${enterpriseTeamsOrgAssignmentLimit}-organization limit.`
          }
          direction="n"
        >
          <Button data-testid="select-orgs-button" inactive>
            {!teamSlug && <OrganizationIcon className="mr-2" />}
            <span>{teamSlug ? 'Add organizations' : 'Select organizations'}</span>
            <TriangleDownIcon className="ml-2" />
          </Button>
        </Tooltip>
      ) : (
        <SelectPanel
          title="Select organizations"
          open={isSelectPanelOpen}
          selected={items.filter(item => addingSelectedOrganizations.some(org => org.id === item.id))}
          onOpenChange={setSelectPanelOpen}
          disableFullscreenOnNarrow
          items={items}
          loading={searchQueryPending || filter !== debouncedFilter}
          placeholderText="Search organizations"
          filterValue={filter}
          onFilterChange={handleFilterChange}
          renderAnchor={({id, 'aria-labelledby': ariaLabelledBy, ...anchorProps}) => (
            <Button
              id={id}
              aria-labelledby={ariaLabelledBy}
              data-testid="select-orgs-button"
              className="pr-3"
              trailingAction={TriangleDownIcon}
              onClick={() => {
                setAddingSelectedOrganizations([])
                setSelectPanelOpen(true)
              }}
              variant={teamSlug ? 'primary' : 'default'}
              {...anchorProps}
            >
              {!teamSlug && <OrganizationIcon className="mr-2" />}
              <span>{teamSlug ? 'Add organizations' : 'Select organizations'}</span>
            </Button>
          )}
          onSelectedChange={(selectedItems: ItemInput[]) => {
            // Find the item that was just clicked (the one that differs from the current selection)
            const selectedItemIds = selectedItems.map(item => item.id)
            const currentSelectedIds = addingSelectedOrganizations.map(org => org.id)

            // Find the ID that was just toggled (either added or removed)
            const addedIds = selectedItemIds.filter(
              (id): id is number => typeof id === 'number' && !currentSelectedIds.includes(id),
            )
            const removedIds = currentSelectedIds.find(id => !selectedItemIds.includes(id))

            // The toggled ID is either the one that was added or removed
            const toggledId = addedIds.length > 0 ? addedIds[0] : removedIds

            if (toggledId !== undefined) {
              // Find the organization that corresponds to this ID
              const org = eligibleOrganizations.find(o => o.id === toggledId)

              if (org) {
                // Toggle the organization in the addingSelectedOrganizations state
                if (addingSelectedOrganizations.some(o => o.id === org.id)) {
                  setAddingSelectedOrganizations(addingSelectedOrganizations.filter(o => o.id !== org.id))
                } else {
                  setAddingSelectedOrganizations([...addingSelectedOrganizations, org])
                }
              }
            }
          }}
          notice={
            searchQueryError && !addErrorOccurred
              ? {
                  variant: 'error',
                  text: 'Something went wrong. Please try again.',
                }
              : addErrorOccurred && !searchQueryError
                ? {
                    variant: 'error',
                    text: addError?.message || 'Something went wrong while adding organizations. Please try again.',
                  }
                : !searchQueryError && !addErrorOccurred && assignmentAllowedToAddLimitReached
                  ? {
                      variant: 'warning',
                      text: `${enterpriseTeamsOrgAssignmentLimit}-organization limit reached. Please remove some organizations before adding more.`,
                    }
                  : undefined
          }
          message={
            eligibleOrganizations.length === 0
              ? searchResults?.totalAvailableCount === 0
                ? {
                    variant: 'empty',
                    title: 'No more organizations to add',
                    body: 'All organizations of your enterprise have been added to this team.',
                  }
                : {
                    variant: 'empty',
                    title: 'No organizations found',
                    body: 'Try a different search term',
                  }
              : undefined
          }
          secondaryAction={
            <div className="d-flex" style={{width: '100%', padding: '3px'}}>
              <Button
                variant="default"
                size="small"
                onClick={handleCancel}
                className={`${styles.orgSearchFooterButton}`}
                style={{marginLeft: 'auto'}}
              >
                Cancel
              </Button>
              <Button
                data-testid="add-orgs"
                variant="primary"
                size="small"
                onClick={() => {
                  if (addingSelectedOrganizations.length > 0) {
                    handleAddOrganizations()
                  } else {
                    handleCancel()
                  }
                }}
                className={`${styles.orgSearchFooterButton}`}
                style={{marginLeft: '8px'}}
              >
                Add
                {addingSelectedOrganizations.length > 0 && (
                  <>
                    {' '}
                    <CounterLabel scheme="secondary" className={styles.addCounterLabel}>
                      {addingSelectedOrganizations.length}
                    </CounterLabel>
                  </>
                )}
              </Button>
            </div>
          }
          overlayProps={{
            width: 'medium',
            maxHeight: 'large',
          }}
        />
      )}
    </>
  )
}

try{ OrganizationSelectPanel.displayName ||= 'OrganizationSelectPanel' } catch {}